import React from 'react';
import {useS, en, DUR, interpolate, clamp, Camara, AbsoluteFill} from './kit';

export const SUBS = {arriba: 230, acento: '#ffd784'};

// ---------- ayudas de tiempo (todo sale de las palabras de la voz) ----------
const ramp = (s: number, a: number, b: number) => interpolate(s, [a, b], [0, 1], clamp);
const rp = (s: number, a: number, b: number) => { const k = ramp(s, a, b); return k * k * (3 - 2 * k); };
const mix = (a: number, b: number, k: number) => a + (b - a) * k;
const rad = (d: number) => (d * Math.PI) / 180;
const lim = (sx: number, sy: number, L: number, a: number): [number, number] => [sx + L * Math.sin(rad(a)), sy + L * Math.cos(rad(a))];
const wrap = (x: number, span: number, off = 300) => ((((x + off) % span) + span) % span) - off;

const E = {
  soldados: en('soldados'), llevaron: en('llevaron'), israel: en('Israel'), ahora: en('ahora'), casa: en('casa'),
  nam2: en('Naamán', 2), gen2: en('general', 2), famoso: en('famoso'), valiente: en('valiente'), rico: en('rico'),
  respetado: en('respetado'), leproso: en('leproso'), nina: en('niña'), esclava2: en('esclava', 2),
  siq: en('siquiera'), sabemos: en('sabemos'), nombre: en('nombre'),
  callarse: en('callarse'), alegrarse: en('alegrarse'), enfermedad: en('enfermedad'), pero2: en('pero', 2),
  dijo: en('dijo'), senora: en('señora'), rogase: en('rogase'), profeta: en('profeta'), samaria: en('Samaria'),
  sanaria: en('sanaría'), lepra: en('lepra'),
  nam3: en('Naamán', 3), fue: en('fue'), caballos: en('caballos'), carros: en('carros'), regalos: en('regalos'),
  profeta2: en('profeta', 2), eliseo: en('Eliseo'), salio: en('salió'), recibirlo: en('recibirlo'),
  mando: en('mandó'), lavara: en('lavara'), siete: en('siete'), rio: en('río'), jordan: en('Jordán'),
  enojo: en('enojó'), regresa: en('regresa'), criados: en('criados'), convencieron: en('convencieron'),
  metio: en('metió'), agua: en('agua'), carne: en('carne'), nino: en('niño'),
  fijate: en('Fíjate'), eso: en('eso'), termino: en('Terminó'), gracias: en('gracias'), nombra: en('nombra'),
  dios: en('Dios'), voz: en('voz'), vida: en('vida'), crees: en('Crees'), responde: en('Responde'), si3: en('sí', 3),
};

// ---------- gradientes comunes ----------
const Defs: React.FC = () => (
  <defs>
    <linearGradient id="gSkyP" gradientUnits="userSpaceOnUse" x1="0" y1="-300" x2="0" y2="1000"><stop offset="0" stopColor="#4f72a8" /><stop offset=".55" stopColor="#8ea6c8" /><stop offset=".85" stopColor="#f2c28f" /><stop offset="1" stopColor="#ffe4b2" /></linearGradient>
    <linearGradient id="gBronze" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#f0c36a" /><stop offset=".55" stopColor="#c4903f" /><stop offset="1" stopColor="#8a5a24" /></linearGradient>
    <linearGradient id="gRed" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#c9503a" /><stop offset="1" stopColor="#80261e" /></linearGradient>
    <linearGradient id="gCrema" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#fbf0d6" /><stop offset="1" stopColor="#d6bf93" /></linearGradient>
    <linearGradient id="gBlue" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#5b86c9" /><stop offset="1" stopColor="#2b4a85" /></linearGradient>
    <linearGradient id="gClay" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#d8844c" /><stop offset="1" stopColor="#8c4524" /></linearGradient>
    <linearGradient id="gStone" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#efdcb3" /><stop offset="1" stopColor="#c3a674" /></linearGradient>
    <linearGradient id="gWood" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#9a6838" /><stop offset="1" stopColor="#5d3a1c" /></linearGradient>
    <linearGradient id="gCol" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stopColor="#bfa273" /><stop offset=".45" stopColor="#f5e6c3" /><stop offset="1" stopColor="#c7ab7b" /></linearGradient>
    <linearGradient id="gAgua" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#a6e0e2" /><stop offset="1" stopColor="#2e7e96" /></linearGradient>
    <linearGradient id="gSuelo" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#e9cb98" /><stop offset="1" stopColor="#b78a5a" /></linearGradient>
    <radialGradient id="gGlow"><stop offset="0" stopColor="#fff0c0" stopOpacity=".95" /><stop offset="1" stopColor="#ffd87a" stopOpacity="0" /></radialGradient>
    <radialGradient id="gVig"><stop offset=".55" stopColor="#2a1608" stopOpacity="0" /><stop offset="1" stopColor="#2a1608" stopOpacity=".34" /></radialGradient>
    <linearGradient id="sk_nina" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#d08e62" /><stop offset="1" stopColor="#99603d" /></linearGradient>
    <linearGradient id="sk_general" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#d9a070" /><stop offset="1" stopColor="#a06c43" /></linearGradient>
    <linearGradient id="sk_dama" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#e6b88a" /><stop offset="1" stopColor="#b8825a" /></linearGradient>
    <linearGradient id="sk_criado" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#bb7f56" /><stop offset="1" stopColor="#80502f" /></linearGradient>
    <linearGradient id="sk_soldado" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#c68e5f" /><stop offset="1" stopColor="#8f5f3a" /></linearGradient>
  </defs>
);

// ---------- ambiente que nunca se queda quieto ----------
const Polvo: React.FC<{s: number; n?: number; col?: string; y0?: number; y1?: number}> = ({s, n = 34, col = '#fff1c4', y0 = 200, y1 = 1900}) => (
  <g>
    {Array.from({length: n}, (_, i) => {
      const sp = 14 + (i % 5) * 9;
      const sp2 = y1 - y0;
      const yy = y0 + ((((i * 197) % sp2) - s * sp) % sp2 + sp2) % sp2;
      return <circle key={i} cx={((i * 173) % 1180) - 50 + Math.sin(s * 0.5 + i) * 26} cy={yy} r={2 + (i % 4)} fill={col} opacity={0.22 + 0.3 * Math.abs(Math.sin(s * 0.9 + i))} />;
    })}
  </g>
);
const Rayos: React.FC<{s: number; col?: string; op?: number; x0?: number}> = ({s, col = '#fff0bf', op = 0.16, x0 = 700}) => (
  <g>
    {[0, 1, 2, 3].map((i) => {
      const a = x0 + i * 190 + Math.sin(s * 0.35 + i * 1.7) * 70;
      return <path key={i} d={`M${a} -500 L${a + 90 + i * 20} -500 L${a - 520 + Math.sin(s * 0.3 + i) * 90} 2000 L${a - 760 + Math.sin(s * 0.3 + i) * 90} 2000Z`} fill={col} opacity={op * (0.55 + 0.45 * Math.sin(s * 0.7 + i * 2))} />;
    })}
  </g>
);

// ---------- piezas dibujadas ----------
const Jar: React.FC<{x: number; y: number; sc?: number; rot?: number}> = ({x, y, sc = 1, rot = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`}>
    <ellipse cx="0" cy="62" rx="44" ry="10" fill="#3b2412" opacity=".25" />
    <path d="M-26 -52 Q-58 -4 -34 50 Q0 68 34 50 Q58 -4 26 -52 Z" fill="url(#gClay)" />
    <path d="M-20 -52 Q-26 -74 -16 -88 L16 -88 Q26 -74 20 -52 Z" fill="url(#gClay)" />
    <ellipse cx="0" cy="-90" rx="22" ry="7" fill="#6e3a1c" />
    <path d="M-44 0 Q0 18 44 0" stroke="#f3d08a" strokeWidth="6" fill="none" opacity=".8" />
    <path d="M-30 -36 Q-46 -6 -28 28" stroke="#ffe0b0" strokeWidth="6" fill="none" opacity=".4" strokeLinecap="round" />
  </g>
);

type Kind = 'nina' | 'general' | 'dama' | 'criado' | 'soldado';
type Arm = [number, number];
type PP = {s: number; kind: Kind; x: number; y: number; sc?: number; flip?: boolean; op?: number; aL?: Arm; aR?: Arm; walk?: number; amp?: number; look?: number; talk?: number; sad?: number; flush?: number; cape?: number; wrapArm?: number; patch?: number; lean?: number; glow?: number; legs?: boolean; jar?: boolean; ph?: number; shh?: number};
const SLEEVE: Record<Kind, string> = {nina: '#f4e6c8', general: '#a8362a', dama: '#3d62a6', criado: '#8d6339', soldado: '#a8362a'};

const Persona: React.FC<PP> = ({s, kind, x, y, sc = 1, flip = false, op = 1, aL = [8, 4], aR = [-8, -4], walk = 0, amp = 0, look = 0, talk = 0, sad = 0, flush = 0, cape = 0, wrapArm = 0, patch = 0, lean = 0, glow = 0, legs = true, jar = false, ph = 0, shh = 0}) => {
  const kid = kind === 'nina';
  const blink = (s + ph) % 4.3 < 0.12 ? 0.1 : 1;
  const sk = `url(#sk_${kind})`;
  const skFlat = kind === 'nina' ? '#b97a52' : kind === 'general' ? '#c68c5c' : kind === 'dama' ? '#d9a87a' : kind === 'criado' ? '#a96f48' : '#b98153';
  const sh: [number, number][] = [[-42, -455], [42, -455]];
  const bob = Math.abs(Math.sin(walk)) * 9 * amp;
  const swing = Math.sin(walk) * amp;
  const armDraw = (i: number, a: Arm) => {
    const [sx, sy] = sh[i];
    const [ex, ey] = lim(sx, sy, 108, a[0]);
    const [hx, hy] = lim(ex, ey, 98, a[1]);
    return {sx, sy, ex, ey, hx, hy};
  };
  const L = armDraw(0, aL);
  const R = armDraw(1, aR);
  const drawArm = (g: ReturnType<typeof armDraw>, key: string, isR: boolean) => (
    <g key={key}>
      <path d={`M${g.sx} ${g.sy}L${g.ex} ${g.ey}`} stroke={SLEEVE[kind]} strokeWidth={kind === 'dama' || kind === 'criado' ? 46 : 40} strokeLinecap="round" />
      <path d={`M${g.ex} ${g.ey}L${g.hx} ${g.hy}`} stroke={kind === 'dama' || kind === 'criado' ? SLEEVE[kind] : skFlat} strokeWidth={30} strokeLinecap="round" />
      <path d={`M${g.ex} ${g.ey}L${g.hx} ${g.hy}`} stroke={skFlat} strokeWidth={26} strokeLinecap="round" opacity={kind === 'dama' || kind === 'criado' ? 0 : 0} />
      <circle cx={g.hx} cy={g.hy} r={19} fill={skFlat} />
      <circle cx={g.hx - 5} cy={g.hy - 6} r={6} fill="#fff" opacity=".2" />
      {isR && patch > 0 && [0.25, 0.5, 0.75].map((u, k) => (
        <ellipse key={k} cx={mix(g.ex, g.hx, u)} cy={mix(g.ey, g.hy, u)} rx={15 + k * 2} ry={11} fill="#f7ece3" stroke="#e2c9ba" strokeWidth="2" opacity={patch} transform={`rotate(${k * 40} ${mix(g.ex, g.hx, u)} ${mix(g.ey, g.hy, u)})`} />
      ))}
      {isR && wrapArm > 0 && (
        <>
          <path d={`M${g.sx} ${g.sy}L${g.ex} ${g.ey}L${g.hx} ${g.hy}`} stroke="url(#gRed)" strokeWidth={70} strokeLinecap="round" strokeLinejoin="round" opacity={wrapArm} />
          {patch > 0 && <ellipse cx={mix(g.ex, g.hx, 0.92)} cy={mix(g.ey, g.hy, 0.92)} rx={13} ry={9} fill="#f7ece3" opacity={patch * wrapArm * 0.9} />}
        </>
      )}
    </g>
  );
  const sw = Math.sin(s * 1.8 + ph) * 14;
  return (
    <g transform={`translate(${x} ${y}) scale(${flip ? -sc : sc} ${sc})`} opacity={op}>
      <ellipse cx="0" cy="4" rx="95" ry="16" fill="#2a1608" opacity=".22" />
      {kind === 'general' && cape > 0 && (
        <path d={`M-46 -462 C${-118 + sw} -400 ${-128 + sw} -200 ${-104 + sw * 1.4} -30 L${100 + sw * 0.6} -30 C${126 + sw} -200 ${116 + sw} -400 46 -462Z`} fill="url(#gRed)" opacity={cape} transform={`translate(0 ${-bob})`} />
      )}
      {kind === 'dama' && <path d="M-62 -300 L-100 0 Q0 24 100 0 L62 -300Z" fill="url(#gBlue)" />}
      {legs && kind !== 'dama' && [-1, 1].map((i) => {
        const p = walk + (i > 0 ? Math.PI : 0);
        const fx = i * 24 + Math.sin(p) * 44 * amp;
        const fy = -Math.max(0, Math.cos(p)) * 16 * amp;
        return (
          <g key={i}>
            <path d={`M${i * 20} -270L${(i * 20 + fx) / 2} -130L${fx} ${fy - 12}`} stroke={kind === 'criado' ? '#7b5a35' : skFlat} strokeWidth={kid ? 34 : 38} strokeLinecap="round" strokeLinejoin="round" fill="none" />
            <ellipse cx={fx + (i > 0 ? 6 : -6)} cy={fy - 6} rx={30} ry={13} fill={kind === 'nina' ? '#6b4a2c' : '#3e2a18'} />
          </g>
        );
      })}
      <g transform={`translate(0 ${-bob}) rotate(${lean} 0 -250)`}>
        {kind === 'nina' && (
          <>
            <path d={`M-46 -462 Q0 -488 46 -462 L${74 + swing * 6} -150 Q0 -126 ${-74 + swing * 6} -150Z`} fill="url(#gCrema)" />
            <path d="M-56 -318 Q0 -296 56 -318" stroke="#c9a46a" strokeWidth="14" fill="none" />
            <path d="M-34 -440 Q-20 -300 -44 -170" stroke="#fff6df" strokeWidth="5" fill="none" opacity=".5" />
          </>
        )}
        {(kind === 'general' || kind === 'soldado') && (
          <>
            <path d="M-54 -462 L54 -462 L68 -230 L-68 -230Z" fill="url(#gRed)" />
            <path d="M-56 -462 Q0 -494 56 -462 L60 -296 Q0 -268 -60 -296Z" fill="url(#gBronze)" stroke="#8a5a24" strokeWidth="3" />
            <path d="M-30 -440 Q0 -420 30 -440M-34 -400 Q0 -380 34 -400M-30 -360 Q0 -340 30 -360" stroke="#8a5a24" strokeWidth="4" fill="none" opacity=".6" />
            {[0, 1, 2, 3, 4, 5].map((i) => <rect key={i} x={-66 + i * 22} y={-262} width={20} height={86 + (i % 2) * 8} rx={8} fill="url(#gRed)" stroke="#6b1d17" strokeWidth="2" />)}
            <rect x={-70} y={-286} width={140} height={28} rx={8} fill="#5d3a1c" />
            <circle cx={0} cy={-272} r={11} fill="url(#gBronze)" />
            <circle cx={-56} cy={-458} r={31} fill="url(#gBronze)" stroke="#8a5a24" strokeWidth="3" />
            <circle cx={56} cy={-458} r={31} fill="url(#gBronze)" stroke="#8a5a24" strokeWidth="3" />
            <path d="M-34 -440 Q-30 -350 -40 -310" stroke="#fff2c8" strokeWidth="6" fill="none" opacity=".35" strokeLinecap="round" />
          </>
        )}
        {kind === 'dama' && (
          <>
            <path d="M-46 -462 Q0 -488 46 -462 L62 -300 L-62 -300Z" fill="url(#gBlue)" />
            <path d="M-60 -300 Q0 -276 60 -300" stroke="#e8c15a" strokeWidth="14" fill="none" />
            {[-26, -12, 0, 12, 26].map((px, i) => <circle key={i} cx={px} cy={-448 + Math.abs(px) * 0.5} r={6} fill="#ffd96a" stroke="#c4903f" strokeWidth="2" />)}
            <path d="M-20 -440 Q-40 -200 -70 -20" stroke="#bcd3f4" strokeWidth="5" fill="none" opacity=".4" />
          </>
        )}
        {kind === 'criado' && (
          <>
            <path d="M-48 -462 Q0 -488 48 -462 L66 -110 L-66 -110Z" fill="#9a7048" />
            <rect x={-60} y={-300} width={120} height={20} rx={8} fill="#5d3a1c" />
            <path d="M-30 -440 Q-34 -300 -44 -140" stroke="#d9b987" strokeWidth="5" fill="none" opacity=".4" />
          </>
        )}
        {drawArm(L, 'aL', false)}
        {drawArm(R, 'aR', true)}
        {glow > 0 && <circle cx={R.hx} cy={R.hy} r={150} fill="url(#gGlow)" opacity={glow} />}
        {jar && <Jar x={104 + Math.sin(walk) * 3} y={-566} sc={0.9} rot={Math.sin(walk) * 3} />}
        <rect x={-22} y={-500} width={44} height={50} rx={16} fill={skFlat} />
        <g transform={`translate(0 -540) rotate(${look * 7}) scale(${kid ? 1.1 : 1})`}>
          {kind === 'dama' && <path d="M-62 -18 Q-70 -74 0 -78 Q70 -74 62 -18 L74 96 Q0 74 -74 96Z" fill="#e3ebf8" opacity=".95" />}
          {kind === 'nina' && <path d="M-46 4 Q-62 60 -42 118" stroke="#24150f" strokeWidth="22" strokeLinecap="round" fill="none" />}
          <ellipse cx="-47" cy="4" rx="9" ry="14" fill={skFlat} />
          <ellipse cx="47" cy="4" rx="9" ry="14" fill={skFlat} />
          <ellipse cx="0" cy="0" rx="47" ry="54" fill={sk} />
          <path d="M-30 -30 Q-38 10 -22 40" stroke="#fff" strokeWidth="6" fill="none" opacity=".16" strokeLinecap="round" />
          {kind === 'nina' && (
            <>
              <path d="M-50 -10 Q-58 -64 0 -68 Q58 -64 50 -10 Q40 -40 0 -44 Q-40 -40 -50 -10Z" fill="#2a1a15" />
              <path d="M-54 -32 Q0 -66 54 -32 L52 -16 Q0 -48 -52 -16Z" fill="url(#gRed)" />
              <path d={`M50 -26 L${88 + Math.sin(s * 3) * 5} ${-10 + Math.sin(s * 2.4) * 4} L72 8 Z`} fill="url(#gRed)" />
              <path d={`M50 -30 L${90 + Math.sin(s * 2.7) * 5} ${-40 + Math.sin(s * 2.1) * 4} L72 -14 Z`} fill="#b8402f" />
            </>
          )}
          {kind === 'general' && (
            <>
              <path d="M-49 -12 Q-54 -66 0 -68 Q54 -66 49 -12 Q38 -42 0 -46 Q-38 -42 -49 -12Z" fill="#1c1512" />
              <path d="M-44 10 Q-48 66 0 80 Q48 66 44 10 Q30 36 0 38 Q-30 36 -44 10Z" fill="#1c1512" />
              <path d="M-14 24 Q0 30 14 24" stroke="#1c1512" strokeWidth="8" fill="none" strokeLinecap="round" />
              <path d="M-50 -38 Q0 -50 50 -38" stroke="url(#gBronze)" strokeWidth="9" fill="none" />
            </>
          )}
          {kind === 'dama' && (
            <>
              <path d="M-48 -14 Q-52 -62 0 -64 Q52 -62 48 -14 Q38 -40 0 -42 Q-38 -40 -48 -14Z" fill="#2a1a15" />
              <path d="M-40 -34 Q0 -52 40 -34" stroke="#ffd96a" strokeWidth="6" fill="none" />
              <circle cx="0" cy="-46" r="6" fill="#d8453a" />
            </>
          )}
          {kind === 'criado' && (
            <>
              <path d="M-54 -8 Q-58 -74 0 -76 Q58 -74 54 -8 Q42 -44 0 -48 Q-42 -44 -54 -8Z" fill="#efe6d2" />
              <path d="M-54 -8 Q-70 30 -58 70 L-44 40Z" fill="#efe6d2" />
              <path d="M-40 16 Q0 62 40 16 Q24 46 0 48 Q-24 46 -40 16Z" fill="#3a2a1d" opacity=".7" />
            </>
          )}
          {kind === 'soldado' && (
            <>
              <path d="M-52 -8 Q-58 -78 0 -82 Q58 -78 52 -8 L40 -24 Q0 -38 -40 -24Z" fill="url(#gBronze)" stroke="#8a5a24" strokeWidth="3" />
              <path d="M-6 -82 Q0 -126 18 -116 Q12 -98 8 -82Z" fill="url(#gRed)" />
            </>
          )}
          {flush > 0 && <ellipse cx="0" cy="8" rx="46" ry="50" fill="#e0452e" opacity={flush * 0.28} />}
          {[-1, 1].map((i) => (
            <g key={i}>
              <ellipse cx={i * 19 + look * 3} cy={-2} rx={kid ? 10.5 : 8.5} ry={(kid ? 13 : 11) * blink} fill="#231510" />
              <circle cx={i * 19 + look * 3 + 3} cy={-6} r={3.4} fill="#fff" opacity={blink} />
              <path d={`M${i * 19 - i * 12} ${-24 - sad * 2} Q${i * 19} ${-30 - sad * 2} ${i * 19 + i * 12} ${-24 - sad * 7}`} stroke={kind === 'general' ? '#1c1512' : '#3b261b'} strokeWidth={kid ? 4 : 5} fill="none" strokeLinecap="round" />
              <circle cx={i * 30} cy={18} r={11} fill="#e8836a" opacity=".32" />
            </g>
          ))}
          <path d="M0 4Q6 18 -2 20" stroke="#8a5434" strokeWidth="4" fill="none" strokeLinecap="round" />
          {shh > 0.1 && <g opacity={shh}><rect x="-6" y="10" width="13" height="44" rx="6.5" fill={skFlat} stroke="#8a5434" strokeWidth="2" /><ellipse cx="14" cy="52" rx="20" ry="14" fill={skFlat} stroke="#8a5434" strokeWidth="2" /></g>}
          {talk > 0.15 ? <ellipse cx="0" cy="34" rx="10" ry={3 + talk * 8 * (0.5 + 0.5 * Math.sin(s * 13 + ph))} fill="#5a1f18" /> : <path d={`M-12 ${34 + sad * 3} Q0 ${34 + 7 - sad * 10} 12 ${34 + sad * 3}`} stroke="#6d2c20" strokeWidth="4.5" fill="none" strokeLinecap="round" />}
        </g>
      </g>
    </g>
  );
};

type CabP = {s: number; x: number; y: number; sc?: number; amp?: number; ph?: number; col?: string; rider?: boolean; girl?: boolean};
const Caballo: React.FC<CabP> = ({s, x, y, sc = 1, amp = 1, ph = 0, col = '#8a5530', rider = false, girl = false}) => {
  const p0 = s * 11 + ph;
  const bob = -Math.abs(Math.sin(p0)) * 12 * amp;
  const leg = (lx: number, off: number, dark: boolean) => {
    const p = p0 + off;
    const fx = lx + Math.sin(p) * 58 * amp;
    const fy = -Math.max(0, Math.cos(p)) * 48 * amp;
    return (
      <g key={lx}>
        <path d={`M${lx} -165L${(lx + fx) / 2 + 16} ${-86 + fy * 0.5}L${fx} ${fy - 8}`} stroke={dark ? '#3d2415' : col} strokeWidth={dark ? 24 : 26} strokeLinecap="round" strokeLinejoin="round" fill="none" />
        <ellipse cx={fx + 4} cy={fy - 3} rx={17} ry={9} fill="#25160c" />
      </g>
    );
  };
  return (
    <g transform={`translate(${x} ${y}) scale(${sc})`}>
      <ellipse cx="20" cy="6" rx="190" ry="18" fill="#2a1608" opacity=".22" />
      {leg(-108, 0, true)}{leg(100, 2.6, true)}
      <g transform={`translate(0 ${bob})`}>
