const Palma: React.FC<{s: number; x: number; y: number; sc?: number; ph?: number; col?: string}> = ({s, x, y, sc = 1, ph = 0, col = '#3d6a3b'}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`}>
