  </g>
);

// ---------- historia de la voz: estado de la niña en el patio ----------
const nina = (s: number) => {
  const flash = s < E.ahora + 1;
  let x = 700, y = 1560, sc = 0.78, amp = 0;
  if (s < E.pero2) {
    x = s < E.ahora ? mix(690, 840, rp(s, 0, E.ahora)) : 840;
    amp = s < E.ahora + 0.4 ? 1 : 0;
  } else if (s < E.pero2 + 1.8) {
    const k = rp(s, E.pero2, E.pero2 + 1.8);
    x = mix(840, 905, k); y = mix(1560, 1135, k); sc = mix(0.78, 0.5, k); amp = 1;
  }
  return {x, y, sc, amp, flash};
};

// ============================ PATIO ============================
const Patio: React.FC<{s: number}> = ({s}) => {
  const g = nina(s);
  const ph = s * 5.2;
  const cover = rp(s, E.siq, E.sabemos + 0.2);
  const heal = 1 - rp(s, E.carne, E.nino);
  const patioFinal = s > E.gracias;
  const patch = patioFinal ? 0 : 1;
  const nam = {x: 360, y: 1240};
  // Naamán vuelve del polvo dorado al final
  const namOp = patioFinal ? rp(s, E.vida + 0.3, E.responde) : 1;
  const jarState = s < E.esclava2 || patioFinal ? 'hombro' : 'suelo';
  const lower = rp(s, E.esclava2, E.esclava2 + 0.9);
  const hold = s >= E.callarse && s < E.pero2;
  const lips = rp(s, E.callarse, E.callarse + 0.45) * (1 - rp(s, E.alegrarse + 0.9, E.pero2));
  const aLg: Arm = lips > 0.01 ? [mix(-12 + Math.sin(ph) * 16 * g.amp, 60, lips), mix(-6, 200, lips)] : [-12 + Math.sin(ph) * 16 * g.amp, -6 + Math.sin(ph) * 8 * g.amp];
  const carrying = jarState === 'hombro';
  const aRg: Arm = carrying ? [60, -150] : [mix(60, 10, lower), mix(-150, 6, lower)];
  const lookG = s < E.esclava2 ? (s < E.nombre ? 0.2 : -0.6) : s < E.callarse ? 1 : s < E.alegrarse ? 0.3 : s < E.pero2 ? -0.8 : patioFinal ? -1 : 0.6;
  const talkG = 0;
  // Naamán
  const prud = rp(s, E.famoso - 0.2, E.famoso + 0.4);
  const valor = rp(s, E.valiente, E.valiente + 0.35) * (1 - rp(s, E.rico, E.rico + 0.4));
  const palm = rp(s, E.rico, E.rico + 0.4) * (1 - rp(s, E.respetado, E.respetado + 0.4));
  const sadN = rp(s, E.leproso, E.leproso + 0.5) * (1 - rp(s, E.nina, E.nina + 0.5));
  const aLn: Arm = valor > 0.1 ? [mix(14, 58, valor), mix(8, 215, valor)] : palm > 0.1 ? [mix(14, -50, palm), mix(8, -105, palm)] : [14 + Math.sin(s * 1.2) * 3, 8];
  const aRn: Arm = patioFinal ? [mix(30, 70, rp(s, E.vida, E.responde)), mix(200, 150, rp(s, E.vida, E.responde))] : [30 + Math.sin(s * 1.5) * 4, 200 + Math.sin(s * 1.1) * 4];
  const guard = rp(s, E.respetado - 0.3, E.respetado + 0.4) * (1 - rp(s, E.nina, E.nina + 0.8));
  const bow = Math.sin(rp(s, E.respetado, E.respetado + 0.9) * Math.PI) * 22 + 6 * guard;
  const coinT = s - E.rico;
  const cx = nam.x + 0.82 * -50;
  // carro que vuelve
  const rt = rp(s, E.nombra - 0.2, E.vida + 0.2);
  const road = patioFinal;
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
      <Defs />
      <rect x={-1100} y={-900} width={3300} height={2100} fill="url(#gSkyP)" />
      <circle cx={830} cy={930 - 20 * Math.sin(s * 0.2)} r={470} fill="url(#gGlow)" opacity={0.85 + (patioFinal ? 0.15 : 0)} />
      <path d="M-200 1010 Q150 860 400 960 T820 930 T1300 990 L1300 1110 L-200 1110Z" fill="#b4aaa8" opacity=".75" />
      <path d="M-200 1050 Q250 940 560 1010 T1300 1010 L1300 1110 L-200 1110Z" fill="#9c9a8f" opacity=".8" />
      <Palma s={s} x={170} y={1030} sc={0.95} ph={0.5} />
      <Palma s={s} x={330} y={1040} sc={0.7} ph={1.4} />
      <Palma s={s} x={960} y={1030} sc={1.05} ph={2.2} />
      <Palma s={s} x={660} y={1046} sc={0.6} ph={3.1} />
      <rect x={-1100} y={1000} width={3300} height={130} fill="url(#gStone)" />
      <path d="M380 1130 L380 960 Q540 800 700 960 L700 1130Z" fill="#fff0c8" />
      <path d="M380 1130 L380 960 Q540 800 700 960 L700 1130Z" fill="none" stroke="#c3a674" strokeWidth="14" />
      <path d="M420 1130 L440 1040 L640 1040 L660 1130Z" fill="#f4d79a" opacity=".6" />
      <rect x={-1100} y={1128} width={3300} height={1000} fill="url(#gSuelo)" />
      {[-1, 0, 1, 2, 3, 4, 5, 6, 7].map((i) => <line key={'v' + i} x1={540 + (i - 3) * 90} y1={1130} x2={540 + (i - 3) * 520} y2={2200} stroke="#a77e50" strokeWidth="4" opacity=".4" />)}
      {[0, 1, 2, 3, 4, 5, 6, 7, 8].map((i) => <line key={'h' + i} x1={-600} y1={1130 + 28 * Math.pow(1.55, i)} x2={1700} y2={1130 + 28 * Math.pow(1.55, i)} stroke="#a77e50" strokeWidth="4" opacity=".4" />)}
      {/* casa a la derecha */}
      <rect x={760} y={690} width={420} height={440} fill="url(#gStone)" stroke="#c3a674" strokeWidth="6" />
      <rect x={740} y={668} width={460} height={34} rx={8} fill="#e0c995" />
      <path d="M840 1130 L840 940 Q900 860 960 940 L960 1130Z" fill="#5a2f1d" />
      <path d="M850 1130 L850 950 Q900 880 950 950 L950 1130Z" fill="#c9733c" opacity={0.55 + 0.2 * Math.sin(s * 3)} />
      <rect x={1010} y={790} width={42} height={92} rx={18} fill="#6e4430" />
      <Columna x={250} y0={640} y1={1128} w={70} />
      <Columna x={830} y0={660} y1={1128} w={64} />
      <rect x={-1100} y={600} width={3300} height={56} fill="#e0c995" />
      <rect x={-1100} y={650} width={3300} height={26} fill="#a98b5a" opacity=".45" />
      <Rayos s={s} x0={780} op={0.17} />
      {/* camino del fondo: carro que vuelve */}
      {road && (
        <g opacity={(rt > 0.01 ? 1 : 0) * (1 - rp(s, E.vida + 0.2, E.crees + 0.6))}>
          <g transform={`translate(${mix(540, 540 + 40, rt)} ${mix(1068, 1125, rt)}) scale(${mix(0.09, 0.42, rt)})`}>
            <Carro s={s} x={-250} y={0} amp={1} />
          </g>
          {[0, 1, 2, 3, 4, 5, 6].map((i) => <circle key={i} cx={540 - 30 + i * 12 + Math.sin(s * 3 + i) * 14} cy={mix(1070, 1130, rt) - 4 - i * 4} r={mix(12, 60, rt) + i * 5} fill="#f2c477" opacity={0.28 * rt * (1 - i / 8)} />)}
        </g>
      )}
      {/* Naamán */}
      <g opacity={namOp}>
        <Persona s={s} kind="general" x={nam.x} y={nam.y} sc={0.82} cape={1} aL={aLn} aR={aRn} look={0.5 - cover * 0.8} sad={sadN} lean={sadN * 3} patch={patch * heal} wrapArm={cover * (1 - (patioFinal ? 1 : 0))} glow={patioFinal ? 0.9 : 0} />
        {prud > 0 && <ellipse cx={nam.x} cy={nam.y - 330} rx={120} ry={210} fill="url(#gGlow)" opacity={0.5 * prud * (1 - rp(s, E.rico + 1, E.respetado))} />}
        {coinT > -0.1 && coinT < 1.6 && [0, 1, 2, 3, 4, 5].map((i) => {
          const u = ramp(coinT, i * 0.07, i * 0.07 + 1.1);
          return <g key={i} opacity={Math.min(1, u * 5) * (1 - u * 0.6)}><ellipse cx={cx + (i - 2.5) * 26 + Math.sin(u * 6 + i) * 10} cy={nam.y - 300 - u * 300 - (i % 2) * 40} rx={16} ry={16} fill="#ffd45a" stroke="#c4903f" strokeWidth="4" /><ellipse cx={cx + (i - 2.5) * 26 + Math.sin(u * 6 + i) * 10 - 4} cy={nam.y - 305 - u * 300 - (i % 2) * 40} rx={5} ry={7} fill="#fff4b8" /></g>;
        })}
      </g>
      {guard > 0.01 && (
        <>
          <Persona s={s} kind="soldado" x={mix(-140, 110, guard)} y={1222} sc={0.74} lean={bow} aL={[12, 6]} aR={[-12, -6]} ph={1} />
          <Persona s={s} kind="soldado" x={mix(1260, 700, guard)} y={1222} sc={0.74} lean={-bow} aL={[12, 6]} aR={[-12, -6]} ph={2} />
        </>
      )}
      {/* niña y cántaro */}
      {!carrying && <Jar x={mix(840 + 80, 960, lower)} y={mix(1560 - 441, 1520, lower)} sc={0.9 * 0.78} rot={mix(0, 0, lower)} />}
      <Persona s={s} kind="nina" x={g.x} y={g.y} sc={g.sc} walk={ph} amp={g.amp} aL={aLg} aR={aRg} look={lookG} shh={lips} jar={carrying && !patioFinal ? true : patioFinal} talk={talkG} lean={hold && lips > 0.5 ? 2 : 0} />
      {patioFinal && <ellipse cx={g.x} cy={g.y - 260} rx={300} ry={460} fill="url(#gGlow)" opacity={0.55 * rp(s, E.nombra, E.dios + 0.5) + 0.18 * Math.sin(s * 2)} />}
