// ============================ RÍO JORDÁN ============================
const WL = 1380;
const Rio: React.FC<{s: number}> = ({s}) => {
  const dips = Array.from({length: 7}, (_, k) => E.metio + k * 0.6);
  const dipV = dips.reduce((a, t) => a + Math.sin(Math.max(0, Math.min(1, (s - t) / 0.52)) * Math.PI), 0);
  const submerge = Math.min(1, dipV) * 640;
  const anger = rp(s, E.enojo - 0.1, E.enojo + 0.3) * (1 - rp(s, E.convencieron, E.convencieron + 0.6));
  const away = rp(s, E.regresa - 0.2, E.regresa + 0.9) * (1 - rp(s, E.convencieron, E.metio));
  const nx = mix(540, 200, away);
  const face = away > 0.4 ? true : false;
  const back = rp(s, E.convencieron, E.metio);
  const posX = s < E.convencieron ? nx : mix(nx, 520, back);
  const cr = rp(s, E.criados - 0.2, E.criados + 0.9);
  const beck = Math.sin(s * 6) * 22 * cr * (1 - rp(s, E.metio, E.metio + 0.5));
  const heal = 1 - rp(s, E.carne, E.nino);
  const joy = rp(s, E.nino - 0.15, E.nino + 0.5);
  const walkN = (anger > 0.1 && away > 0.05 && away < 0.98) ? s * 4 : 0;
  const ampN = (away > 0.02 && away < 0.98) ? 0.5 : 0;
  const ripple = (t: number) => {
    const k = ramp(s, t, t + 1.2);
    return k > 0 && k < 1 ? <ellipse key={t} cx={posX} cy={WL + 20} rx={60 + k * 380} ry={14 + k * 70} fill="none" stroke="#fff4c2" strokeWidth={7 * (1 - k) + 2} opacity={0.9 * (1 - k)} /> : null;
  };
  return (
    <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{position: 'absolute', left: 0, top: 0, overflow: 'visible'}}>
      <Defs />
      <rect x={-1500} y={-900} width={4200} height={2300} fill="url(#gSkyP)" />
      <circle cx={820} cy={880} r={520} fill="url(#gGlow)" opacity=".9" />
      <path d="M-400 1010 Q100 840 520 960 T1500 920 L1500 1100 L-400 1100Z" fill="#9aa0a8" opacity=".7" />
      {[0, 1, 2, 3, 4, 5].map((i) => <Palma key={i} s={s} x={60 + i * 200} y={1080} sc={0.6 + (i % 3) * 0.14} ph={i * 0.9} col="#3d6a3b" />)}
      <rect x={-1500} y={1070} width={4200} height={1000} fill="url(#gAgua)" />
      {Array.from({length: 22}, (_, i) => <ellipse key={i} cx={wrap(i * 150 + Math.sin(s * 0.6 + i) * 30 - s * 20, 1500, 200)} cy={1110 + (i % 9) * 55 + Math.sin(s * 1.1 + i) * 6} rx={50 + (i % 4) * 22} ry={6} fill="#fff5d0" opacity={0.3 + 0.25 * Math.sin(s * 2 + i)} />)}
      {/* orilla cercana */}
      <path d="M-300 1650 Q250 1560 700 1620 T1500 1600 L1500 1920 L-300 1920Z" fill="#c9a76f" />
      <path d="M-300 1700 Q350 1640 800 1690 L1500 1680 L1500 1920 L-300 1920Z" fill="#b48f58" />
      {[0, 1, 2, 3].map((i) => <g key={i} transform={`translate(${60 + i * 330} ${1660 - (i % 2) * 20})`}><path d="M0 0 q-12 -90 -38 -130 M0 0 q6 -100 26 -150 M0 0 q26 -70 70 -100" stroke="#5f873a" strokeWidth="9" fill="none" strokeLinecap="round" />{[0, 1].map((k) => <rect key={k} x={-6 + k * 22} y={-150 - k * 30} width="10" height="40" rx="5" fill="#7a5530" />)}</g>)}
      {/* criados */}
      {cr > 0.01 && (
        <>
          <Persona s={s} kind="criado" x={mix(1400, 900, cr)} y={1740} sc={0.72} walk={s * 5} amp={1 - cr > 0.02 ? 1 : 0} look={-0.5} talk={cr * 0.6} aL={[-70 - beck, -150]} aR={[30, 70]} ph={1} lean={joy * -4} />
          <Persona s={s} kind="criado" x={mix(1600, 790, cr)} y={1780} sc={0.76} walk={s * 5 + 1} amp={1 - cr > 0.02 ? 1 : 0} look={-0.6} talk={cr * 0.6} aL={[-60, -120]} aR={[mix(30, 120, joy) + beck * 0.5, mix(100, 175, joy)]} ph={2} />
        </>
      )}
      {/* general en el agua (recortado por la superficie) */}
      <defs><clipPath id="clipRio"><rect x={-600} y={-2000} width={2400} height={WL + 2000} /></clipPath></defs>
      <g clipPath="url(#clipRio)">
        <g transform={`translate(0 ${submerge})`}>
          <Persona s={s} kind="general" x={posX} y={WL + 250} sc={0.9} cape={0.9} look={0.3 * (1 - joy)} sad={anger * 0.3 + (1 - joy) * 0.2} flush={anger} walk={walkN} amp={ampN}
            lean={anger * Math.sin(s * 14) * 3}
            aL={[mix(-14, -130, anger) + Math.sin(s * 12) * 12 * anger, mix(-8, -170, anger)]}
            aR={[mix(mix(30, 20, anger), 150, joy), mix(200, 200, joy)]}
            patch={heal} glow={joy * (1 - heal) * 1.1} />
        </g>
      </g>
      {/* la luz que sube al salir del agua */}
      <ellipse cx={posX} cy={1000} rx={260} ry={520} fill="url(#gGlow)" opacity={joy * 0.8} />
      {/* agua delante del general */}
      <ellipse cx={posX} cy={WL + 10} rx={170} ry={26} fill="#dff6f2" opacity={0.34 + 0.18 * Math.sin(s * 3)} />
      {[0, 1, 2].map((i) => <ellipse key={i} cx={posX} cy={WL + 22} rx={120 + ((s * 60 + i * 80) % 240)} ry={22 + ((s * 12 + i * 16) % 48)} fill="none" stroke="#e9fbfb" strokeWidth="4" opacity={0.5 * (1 - ((s * 60 + i * 80) % 240) / 240)} />)}
      {dips.map((t) => ripple(t))}
      {dips.map((t, i) => {
        const k = ramp(s, t + 0.2, t + 1.0);
        return k > 0 && k < 1 ? <g key={'o' + i} opacity={1 - k}>{[0, 1, 2, 3, 4].map((j) => <circle key={j} cx={posX + (j - 2) * 62 + Math.sin(j + i) * 20} cy={WL - 20 - k * (180 + j * 40)} r={9 - j} fill="#fff7cf" />)}</g> : null;
      })}
      <rect x={-1500} y={WL + 50} width={4200} height={700} fill="url(#gAgua)" opacity={0.32} />
      <Rayos s={s} x0={820} op={0.2} />
      <Polvo s={s} n={30} col="#fff6d0" />
      <rect x={-300} y={-300} width={1680} height={2520} fill="url(#gVig)" />
    </svg>
  );
};

