  {t: E.criados, x: 620, y: 1400, zoom: 1.1},
  {t: E.convencieron, x: 420, y: 1300, zoom: 1.25},
  {t: E.metio, x: 520, y: 1290, zoom: 1.3},
  {t: E.metio + 3.0, x: 520, y: 1230, zoom: 1.42},
  {t: E.nino, x: 520, y: 1080, zoom: 1.7},
  {t: E.eso, x: 520, y: 1040, zoom: 2.0},
  {t: E.gracias, x: 520, y: 1160, zoom: 1.35},
  {t: E.nombra + 0.3, x: 540, y: 1200, zoom: 1.1},
];

// ============================ ESCENA ============================
export const Escena: React.FC = () => {
  const {s} = useS();
  const aldeaOp = Math.min(rp(s, E.soldados - 0.3, E.soldados + 0.8), 1 - rp(s, E.ahora - 0.2, E.ahora + 1.0));
  const salaOp = rp(s, E.dijo, E.senora + 0.2);
  const camOp = rp(s, E.nam3 - 0.9, E.nam3 + 0.2);
  const eliOp = rp(s, E.profeta2 - 0.2, E.eliseo + 0.2);
  const rioOp = rp(s, E.lavara, E.jordan + 0.3);
  const finOp = rp(s, E.gracias, E.nombra + 0.3);
  const breathe = `translate(${Math.sin(s * 0.31) * 6}px, ${Math.sin(s * 0.23) * 5}px) scale(${1 + 0.012 * Math.sin(s * 0.5)})`;
  return (
    <AbsoluteFill style={{background: '#3a2414', overflow: 'hidden'}}>
      <AbsoluteFill style={{transform: breathe}}>
        {s < E.senora + 0.4 && <AbsoluteFill><Camara paradas={camPatio}><Patio s={s} /></Camara></AbsoluteFill>}
        {aldeaOp > 0.002 && s < E.ahora + 1.3 && <AbsoluteFill style={{opacity: aldeaOp}}><Camara paradas={camAldea}><Aldea s={s} /></Camara></AbsoluteFill>}
        {salaOp > 0.002 && s < E.nam3 + 0.4 && <AbsoluteFill style={{opacity: salaOp}}><Camara paradas={camSala}><Sala s={s} /></Camara></AbsoluteFill>}
        {camOp > 0.002 && s < E.eliseo + 0.4 && <AbsoluteFill style={{opacity: camOp}}><Camara paradas={camCamino}><Camino s={s} /></Camara></AbsoluteFill>}
        {eliOp > 0.002 && s < E.jordan + 0.5 && <AbsoluteFill style={{opacity: eliOp}}><Camara paradas={camEliseo}><Eliseo s={s} /></Camara></AbsoluteFill>}
        {rioOp > 0.002 && s < E.nombra + 0.5 && <AbsoluteFill style={{opacity: rioOp}}><Camara paradas={camRio}><Rio s={s} /></Camara></AbsoluteFill>}
        {finOp > 0.002 && <AbsoluteFill style={{opacity: finOp}}><Camara paradas={camPatio}><Patio s={s} /></Camara></AbsoluteFill>}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
